// The single source for the site frame: every destination, its label, and where it appears.
// The header menu, the footer columns, the 404 suggestions, the hub page titles, and the
// frame audit (tests/browser/frame.spec.ts) all read from here. Add or rename a page here only.

// `intro` marks a hub page generated by src/pages/[page].astro; it is the lead text and meta description.
export const destinations = {
  home: { label: 'Home', href: '/' },
  about: { label: 'About', href: '/about/', intro: 'People, technology, and experience in context.' },
  projects: { label: 'Projects', href: '/projects/', intro: 'Our work across archaeological sites, museums, cities, classrooms, and virtual worlds.' },
  themes: { label: 'Research themes', href: '/about/#themes' },
  presentations: { label: 'Presentations', href: '/presentations/', intro: 'Talks, posters, demonstrations, workshops, and exhibitions.' },
  'awards-funding': { label: 'Awards & funding', href: '/awards-funding/', intro: 'Recognition and support for our research.' },
  people: { label: 'People', href: '/people/', intro: 'An interdisciplinary lab at the University of Illinois Urbana-Champaign.' },
  publications: { label: 'Publications', href: '/publications/', intro: 'Papers, chapters, theses, and preprints from our research.' },
  news: { label: 'News', href: '/news/' },
  join: { label: 'Join', href: '/join/', intro: 'Graduate study in immersive learning and archaeology.' },
  values: { label: 'Lab values', href: '/about/#values' },
  accessibility: { label: 'Accessibility statement', href: '/accessibility/' },
  admin: { label: 'Log in', href: '/admin/' },
};

// Header menu, in display order. A group opens as a disclosure; `sections` lists the
// path prefixes that mark the group as the current section.
export const primaryMenu = [
  { id: 'about' },
  { group: 'Research', items: ['projects', 'themes', 'presentations', 'awards-funding'], sections: ['/projects/', '/themes/', '/presentations/', '/awards-funding/'] },
  { id: 'people' },
  { id: 'publications' },
  { id: 'news' },
  { id: 'join', emphasis: true },
];

// Footer columns. `accessibility-settings` is the button that opens the settings panel, not a page.
export const footerMenu = [
  { heading: 'Explore', items: ['projects', 'publications', 'values', 'admin'] },
  { heading: 'Useful links', items: ['about', 'people', 'accessibility-settings', 'accessibility'] },
];

export const notFoundLinks = ['home', 'projects', 'people', 'publications', 'news'];

export const hubPages = Object.keys(destinations).filter(id => destinations[id].intro);

// The current page comes from the URL, never from a hand-set class. Anchor links are never "current".
export const isCurrent = (href, path) => !href.includes('#') && path.startsWith(href);
export const inSection = (sections, path) => sections.some(prefix => path.startsWith(prefix));

// What the header menu must mark for a given path; used by the frame audit.
export function expectedCurrent(path) {
  const flat = primaryMenu.flatMap(entry => entry.group ? entry.items : [entry.id]);
  return {
    page: flat.filter(id => isCurrent(destinations[id].href, path)).map(id => destinations[id].label),
    section: primaryMenu.filter(entry => entry.group && inSection(entry.sections, path)).map(entry => entry.group),
  };
}
